
PRAGMA foreign_keys=ON;
CREATE TABLE game_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE regions(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,biome TEXT,description TEXT);
CREATE TABLE settlements(id TEXT PRIMARY KEY,region_id TEXT REFERENCES regions(id),name_ko TEXT NOT NULL,description TEXT,security REAL DEFAULT 50,food REAL DEFAULT 50,wealth REAL DEFAULT 50,population INTEGER DEFAULT 0,knowledge_spread REAL DEFAULT 0,divine_surveillance REAL DEFAULT 0,alive INTEGER DEFAULT 1);
CREATE TABLE factions(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,kind TEXT,description TEXT,home_settlement_id TEXT REFERENCES settlements(id));
CREATE TABLE species(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('human','animal','beast')),base_health REAL NOT NULL,base_mana REAL DEFAULT 0,behavior_profile TEXT,description TEXT);
CREATE TABLE beast_species(species_id TEXT PRIMARY KEY REFERENCES species(id),threat_tier TEXT NOT NULL,territoriality REAL NOT NULL,base_mana_yield REAL NOT NULL,preferred_biome TEXT,description TEXT);
CREATE TABLE characters(id TEXT PRIMARY KEY,species_id TEXT NOT NULL REFERENCES species(id),name_ko TEXT NOT NULL,role TEXT,origin TEXT,description TEXT,starting_region_id TEXT REFERENCES regions(id),starting_faction_id TEXT REFERENCES factions(id),is_story_critical INTEGER DEFAULT 0);
CREATE TABLE behavior_nodes(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,category TEXT NOT NULL,description TEXT);
CREATE TABLE behavior_profiles(id TEXT PRIMARY KEY,name_ko TEXT,description TEXT);
CREATE TABLE profile_nodes(profile_id TEXT REFERENCES behavior_profiles(id),node_id INTEGER REFERENCES behavior_nodes(id),base_weight REAL NOT NULL DEFAULT 1,enabled INTEGER DEFAULT 1,PRIMARY KEY(profile_id,node_id));
CREATE TABLE knowledge(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,domain TEXT NOT NULL,description TEXT,discovery_method TEXT,restricted INTEGER DEFAULT 0);
CREATE TABLE spells(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,base_mana_cost REAL NOT NULL,description TEXT);
CREATE TABLE spell_knowledge(spell_id TEXT REFERENCES spells(id),knowledge_id TEXT REFERENCES knowledge(id),efficiency_multiplier REAL NOT NULL DEFAULT 1,conditions_json TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(spell_id,knowledge_id));
CREATE TABLE quests(id TEXT PRIMARY KEY,act INTEGER NOT NULL,title_ko TEXT NOT NULL,summary TEXT,mandatory INTEGER DEFAULT 1,prerequisite_quest_id TEXT REFERENCES quests(id));
CREATE TABLE quest_steps(id TEXT PRIMARY KEY,quest_id TEXT REFERENCES quests(id),step_order INTEGER NOT NULL,objective TEXT,trigger_type TEXT,trigger_payload_json TEXT DEFAULT '{}');
CREATE TABLE lore(id TEXT PRIMARY KEY,category TEXT NOT NULL,title_ko TEXT NOT NULL,body TEXT NOT NULL,secret_level INTEGER DEFAULT 0);
CREATE TABLE event_templates(id TEXT PRIMARY KEY,name_ko TEXT NOT NULL,category TEXT,trigger_json TEXT NOT NULL,effects_json TEXT NOT NULL,description TEXT);
CREATE TABLE simulation_rules(id TEXT PRIMARY KEY,category TEXT NOT NULL,config_json TEXT NOT NULL,description TEXT);
CREATE TABLE world_saves(id TEXT PRIMARY KEY,save_name TEXT,world_time_hours REAL DEFAULT 0,seed INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE entities(id TEXT PRIMARY KEY,save_id TEXT NOT NULL REFERENCES world_saves(id) ON DELETE CASCADE,character_id TEXT REFERENCES characters(id),species_id TEXT NOT NULL REFERENCES species(id),display_name TEXT NOT NULL,region_id TEXT REFERENCES regions(id),settlement_id TEXT REFERENCES settlements(id),faction_id TEXT REFERENCES factions(id),occupation TEXT,alive INTEGER NOT NULL DEFAULT 1,health REAL NOT NULL DEFAULT 100,mana_current REAL NOT NULL DEFAULT 0,mana_max REAL NOT NULL DEFAULT 0,hunger REAL DEFAULT 0,thirst REAL DEFAULT 0,fatigue REAL DEFAULT 0,fear REAL DEFAULT 0,anger REAL DEFAULT 0,stress REAL DEFAULT 0,wealth REAL DEFAULT 0,position_x REAL,position_y REAL,position_z REAL,profile_id TEXT REFERENCES behavior_profiles(id),state_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX idx_entities_region ON entities(save_id,region_id,alive);
CREATE TABLE entity_traits(entity_id TEXT REFERENCES entities(id) ON DELETE CASCADE,trait TEXT NOT NULL,value REAL NOT NULL,PRIMARY KEY(entity_id,trait));
CREATE TABLE entity_goals(id TEXT PRIMARY KEY,entity_id TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,goal_type TEXT NOT NULL,target_entity_id TEXT REFERENCES entities(id),priority REAL DEFAULT 0,status TEXT DEFAULT 'active',context_json TEXT DEFAULT '{}');
CREATE TABLE relationships(save_id TEXT REFERENCES world_saves(id),source_id TEXT REFERENCES entities(id),target_id TEXT REFERENCES entities(id),affection REAL DEFAULT 0,trust REAL DEFAULT 0,attraction REAL DEFAULT 0,respect REAL DEFAULT 0,fear REAL DEFAULT 0,resentment REAL DEFAULT 0,familiarity REAL DEFAULT 0,commitment REAL DEFAULT 0,relation_type TEXT DEFAULT 'acquaintance',PRIMARY KEY(save_id,source_id,target_id),CHECK(source_id<>target_id));
CREATE TABLE family_links(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),entity_a TEXT REFERENCES entities(id),entity_b TEXT REFERENCES entities(id),link_type TEXT NOT NULL,start_hour REAL,end_hour REAL);
CREATE TABLE inventories(id TEXT PRIMARY KEY,owner_entity_id TEXT REFERENCES entities(id),item_id TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 1,properties_json TEXT DEFAULT '{}');
CREATE TABLE memories(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),entity_id TEXT REFERENCES entities(id),event_id TEXT,subject_entity_id TEXT REFERENCES entities(id),memory_type TEXT NOT NULL,intensity REAL DEFAULT 1,confidence REAL DEFAULT 1,occurred_hour REAL NOT NULL,details_json TEXT DEFAULT '{}');
CREATE INDEX idx_memories_actor ON memories(entity_id,occurred_hour);
CREATE TABLE world_events(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),event_type TEXT NOT NULL,region_id TEXT REFERENCES regions(id),actor_id TEXT REFERENCES entities(id),target_id TEXT REFERENCES entities(id),occurred_hour REAL NOT NULL,payload_json TEXT DEFAULT '{}');
CREATE INDEX idx_events_time ON world_events(save_id,occurred_hour);
CREATE TABLE event_witnesses(event_id TEXT REFERENCES world_events(id),witness_id TEXT REFERENCES entities(id),perceived_json TEXT DEFAULT '{}',PRIMARY KEY(event_id,witness_id));
CREATE TABLE crimes(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),event_id TEXT REFERENCES world_events(id),suspect_id TEXT REFERENCES entities(id),victim_id TEXT REFERENCES entities(id),crime_type TEXT NOT NULL,settlement_id TEXT REFERENCES settlements(id),reported INTEGER DEFAULT 0,investigation_status TEXT DEFAULT 'unknown',bounty REAL DEFAULT 0);
CREATE TABLE contracts(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),contract_type TEXT NOT NULL,party_a TEXT REFERENCES entities(id),party_b TEXT REFERENCES entities(id),faction_id TEXT REFERENCES factions(id),status TEXT DEFAULT 'active',terms_json TEXT DEFAULT '{}');
CREATE TABLE faction_memberships(entity_id TEXT REFERENCES entities(id),faction_id TEXT REFERENCES factions(id),rank TEXT,loyalty REAL DEFAULT 50,PRIMARY KEY(entity_id,faction_id));
CREATE TABLE settlement_states(save_id TEXT REFERENCES world_saves(id),settlement_id TEXT REFERENCES settlements(id),security REAL DEFAULT 50,food REAL DEFAULT 50,wealth REAL DEFAULT 50,population INTEGER DEFAULT 0,knowledge_spread REAL DEFAULT 0,divine_surveillance REAL DEFAULT 0,damaged REAL DEFAULT 0,PRIMARY KEY(save_id,settlement_id));
CREATE TABLE territories(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),region_id TEXT REFERENCES regions(id),dominant_entity_id TEXT REFERENCES entities(id),species_id TEXT REFERENCES species(id),food_supply REAL DEFAULT 100,disturbance REAL DEFAULT 0,territorial_pressure REAL DEFAULT 0,center_x REAL,center_z REAL,radius REAL,properties_json TEXT DEFAULT '{}');
CREATE TABLE populations(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),region_id TEXT REFERENCES regions(id),species_id TEXT REFERENCES species(id),count INTEGER NOT NULL,food_supply REAL DEFAULT 100,predation_pressure REAL DEFAULT 0,updated_hour REAL DEFAULT 0);
CREATE TABLE entity_knowledge(entity_id TEXT REFERENCES entities(id),knowledge_id TEXT REFERENCES knowledge(id),mastery REAL NOT NULL DEFAULT 0,discovered_hour REAL DEFAULT 0,source TEXT,PRIMARY KEY(entity_id,knowledge_id));
CREATE TABLE mana_absorptions(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),mage_entity_id TEXT REFERENCES entities(id),beast_entity_id TEXT REFERENCES entities(id),occurred_hour REAL NOT NULL,beast_mana REAL NOT NULL,relative_factor REAL NOT NULL,repetition_factor REAL NOT NULL,absorbed_amount REAL NOT NULL);
CREATE TABLE mana_hunt_history(mage_entity_id TEXT REFERENCES entities(id),beast_species_id TEXT REFERENCES beast_species(species_id),kill_count INTEGER DEFAULT 0,PRIMARY KEY(mage_entity_id,beast_species_id));
CREATE TABLE quest_progress(save_id TEXT REFERENCES world_saves(id),quest_id TEXT REFERENCES quests(id),status TEXT NOT NULL DEFAULT 'locked',current_step INTEGER DEFAULT 0,context_json TEXT DEFAULT '{}',PRIMARY KEY(save_id,quest_id));
CREATE TABLE active_actions(entity_id TEXT PRIMARY KEY REFERENCES entities(id),node_id INTEGER REFERENCES behavior_nodes(id),target_id TEXT REFERENCES entities(id),started_hour REAL,minimum_end_hour REAL,cooldown_until_hour REAL,context_json TEXT DEFAULT '{}');
CREATE TABLE simulation_jobs(id TEXT PRIMARY KEY,save_id TEXT REFERENCES world_saves(id),job_type TEXT NOT NULL,region_id TEXT REFERENCES regions(id),due_hour REAL NOT NULL,status TEXT DEFAULT 'pending',payload_json TEXT DEFAULT '{}');
